40: export function App() {
41:   const [lang, setLang] = useState(getCurrentLanguage());
42:   const [candleOn, setCandleOn] = useState(isCandleMode());
43:   const [batsOn, setBatsOn] = useState(false);
44:   const [flash, setFlash] = useState(false);
45:   const clickTimestamps = useRef<number[]>([]);
46:   const activePath = window.location.pathname;
47: 
48:   const handleLogoClick = useCallback(() => {
49:     const now = Date.now();
50:     clickTimestamps.current.push(now);
51:     const recent = clickTimestamps.current.filter((t) => now - t < 2000);
52:     clickTimestamps.current = recent;
53:     if (recent.length >= 5) {
54:       clickTimestamps.current = [];
55:       setFlash(true);
56:       setTimeout(() => setFlash(false), 2000);
57:     }
58:   }, []);
59: 
60:   const handleLang = useCallback((l: string) => {
61:     changeLanguage(l);
62:     setLang(l);
63:   }, []);
64: 
65:   const handleCandle = useCallback(() => {
66:     toggleCandleMode();
67:     setCandleOn((v) => !v);
68:   }, []);
69: 
70:   const handleBats = useCallback(() => {
71:     if (batsOn) {
72:       stopBats();
73:     } else {
74:       startBats();
75:     }
76:     setBatsOn((v) => !v);
77:   }, [batsOn]);
78: 
79:   useEffect(() => {
80:     const updatePath = () => setLang(getCurrentLanguage());
81:     window.addEventListener("popstate", updatePath);
82:     return () => window.removeEventListener("popstate", updatePath);
83:   }, []);
84: 
85:   const langs = ["pt", "en", "es"];
86: 
87:   return (
88:     <>
89:       <header className="halloween-navbar">
90:         <span className="halloween-navbar__logo" onClick={handleLogoClick}>
91:           HALLOWEEN
92:         </span>
93:         <nav className="halloween-navbar__nav">
94:           {links.map((link) => (
95:             <a
96:               key={link.href}
97:               href={link.href}
98:               className={
99:                 "halloween-navbar__link" +
100:                 (activePath === link.href ? " halloween-navbar__link--active" : "")
101:               }
102:               onClick={(e) => {
103:                 e.preventDefault();
104:                 window.history.pushState(null, "", link.href);
105:                 window.dispatchEvent(new PopStateEvent("popstate"));
106:               }}
107:             >
108:               {t(link.key)}
109:             </a>
110:           ))}
111:         </nav>
112:         <div className="halloween-navbar__controls">
113:           {langs.map((l) => (
114:             <button
115:               key={l}
116:               className={
117:                 "halloween-navbar__btn" +
118:                 (lang === l ? " halloween-navbar__btn--active" : "")
119:               }
120:               onClick={() => handleLang(l)}
121:             >
122:               {l.toUpperCase()}
123:             </button>
124:           ))}
125:           <span className="halloween-navbar__divider" />
126:           <button
127:             className={
128:               "halloween-navbar__btn" +
129:               (candleOn ? " halloween-navbar__btn--active" : "")
130:             }
131:             onClick={handleCandle}
132:             title="Candle mode"
133:           >
134:             <CandleIcon on={candleOn} />
135:           </button>
136:           <button
137:             className={
138:               "halloween-navbar__btn" +
139:               (batsOn ? " halloween-navbar__btn--active" : "")
140:             }
141:             onClick={handleBats}
142:             title="Release the bats"
143:           >
144:             <BatIcon on={batsOn} />
145:           </button>
146:         </div>
147:       </header>
148:       {flash && (
149:         <div className="halloween-flash">
150:           <span className="halloween-flash__text">{t("halloween.boo")}</span>
151:           <span className="halloween-flash__sub">{t("halloween.scare")}</span>
152:         </div>
153:       )}
154:     </>
155:   );
156: }

